package com.example.pakebdh_7816;

import java.security.MessageDigest;
import java.util.Arrays;

/** Host-only profile checks; expected bytes are independently generated by Python. */
public final class PakeEmvProtocolTest {
    private static int checks;

    private static byte[] pattern(int length, int seed) {
        byte[] out = new byte[length];
        for (int i = 0; i < length; ++i) out[i] = (byte) (17 * i + seed);
        return out;
    }

    private static void check(boolean condition) {
        ++checks;
        if (!condition) throw new AssertionError("check " + checks + " failed");
    }

    private interface Operation { void run() throws Exception; }

    private static void rejects(Operation operation) throws Exception {
        ++checks;
        try {
            operation.run();
        } catch (IllegalArgumentException expected) {
            return;
        }
        throw new AssertionError("invalid input accepted at check " + checks);
    }

    private static void emit(String name, byte[] bytes) {
        StringBuilder line = new StringBuilder(name).append('=');
        for (byte b : bytes) line.append(String.format("%02x", b & 255));
        System.out.println(line);
    }

    public static void main(String[] args) throws Exception {
        byte[] tk = pattern(32, 1), ss = pattern(32, 2);
        byte[] x1 = pattern(832, 3), x2 = pattern(800, 4), nu = pattern(32, 5);
        byte[] ecert = pattern(8220, 6), ec = pattern(796, 7);
        byte[] pkC = pattern(800, 8), pkIS = pattern(1312, 9);
        byte[] ctx1 = PakeEmvProtocol.ctx1(x1, x2); emit("ctx1", ctx1);
        byte[] pi1 = PakeEmvProtocol.kc1(tk, ctx1, nu); emit("pi1", pi1);
        byte[] m3 = new byte[64];
        System.arraycopy(nu, 0, m3, 0, 32);
        System.arraycopy(pi1, 0, m3, 32, 32);
        byte[] ctx2 = PakeEmvProtocol.ctx2(m3, ctx1); emit("ctx2", ctx2);
        byte[] kcert = PakeEmvProtocol.certKey(tk, ctx2); emit("kcert", kcert);
        byte[] ctx3 = PakeEmvProtocol.ctx3(ecert, ctx2); emit("ctx3", ctx3);
        byte[] kec = PakeEmvProtocol.ec2Key(tk, ctx3); emit("kec", kec);
        byte[] ctx4 = PakeEmvProtocol.ctx4(ec, ctx3); emit("ctx4", ctx4);
        byte[] pkh = PakeEmvProtocol.pkh(pkC, pkIS); emit("pkh", pkh);
        PakeEmvProtocol.Keys keys = PakeEmvProtocol.deriveKeys(tk, ss, pkh, ctx4);
        emit("key", keys.finalKey); emit("k2", keys.k2); emit("k3", keys.k3);
        byte[] pi2 = PakeEmvProtocol.kc2(keys.k2, ctx4); emit("pi2", pi2);
        byte[] ctx5 = PakeEmvProtocol.ctx5(pi2, ctx4); emit("ctx5", ctx5);
        byte[] pi3 = PakeEmvProtocol.kc3(keys.k3, ctx5); emit("pi3", pi3);

        check(!Arrays.equals(keys.finalKey, keys.k2));
        check(!Arrays.equals(keys.finalKey, keys.k3));
        check(!Arrays.equals(keys.k2, keys.k3));
        check(!Arrays.equals(PakeEmvProtocol.certKey(tk, ctx3), kec));
        check(!Arrays.equals(PakeEmvProtocol.kc2(keys.k3, ctx5), pi3));
        x1[0] ^= 1;
        check(!Arrays.equals(ctx1, PakeEmvProtocol.ctx1(x1, x2)));
        x1[0] ^= 1;
        x1[831] ^= 1;
        check(!Arrays.equals(ctx1, PakeEmvProtocol.ctx1(x1, x2)));
        x1[831] ^= 1;
        for (int p : new int[]{0, 31, 32, 799}) {
            x2[p] ^= 1;
            check(!Arrays.equals(ctx1, PakeEmvProtocol.ctx1(x1, x2)));
            x2[p] ^= 1;
        }
        nu[31] ^= 1;
        check(!Arrays.equals(pi1, PakeEmvProtocol.kc1(tk, ctx1, nu)));
        nu[31] ^= 1;
        m3[63] ^= 1;
        check(!Arrays.equals(ctx2, PakeEmvProtocol.ctx2(m3, ctx1)));
        m3[63] ^= 1;
        ecert[8219] ^= 1;
        check(!Arrays.equals(ctx3, PakeEmvProtocol.ctx3(ecert, ctx2)));
        ecert[8219] ^= 1;
        for (int p : new int[]{0, 12, 795}) {
            ec[p] ^= 1;
            check(!Arrays.equals(ctx4, PakeEmvProtocol.ctx4(ec, ctx3)));
            ec[p] ^= 1;
        }
        pkC[799] ^= 1;
        check(!Arrays.equals(pkh, PakeEmvProtocol.pkh(pkC, pkIS)));
        pkC[799] ^= 1;
        pkIS[1311] ^= 1;
        check(!Arrays.equals(pkh, PakeEmvProtocol.pkh(pkC, pkIS)));
        pkIS[1311] ^= 1;
        ss[0] ^= 1;
        PakeEmvProtocol.Keys changedKeys = PakeEmvProtocol.deriveKeys(tk, ss, pkh, ctx4);
        ss[0] ^= 1;
        check(!Arrays.equals(keys.finalKey, changedKeys.finalKey));
        check(!Arrays.equals(keys.k2, changedKeys.k2));
        check(!Arrays.equals(keys.k3, changedKeys.k3));
        pkh[0] ^= 1;
        check(!Arrays.equals(keys.finalKey, PakeEmvProtocol.deriveKeys(tk, ss, pkh, ctx4).finalKey));
        pkh[0] ^= 1;
        ctx4[0] ^= 1;
        check(!Arrays.equals(keys.finalKey, PakeEmvProtocol.deriveKeys(tk, ss, pkh, ctx4).finalKey));
        ctx4[0] ^= 1;
        pi2[31] ^= 1;
        check(!Arrays.equals(ctx5, PakeEmvProtocol.ctx5(pi2, ctx4)));
        pi2[31] ^= 1;

        byte[] certC = pattern(1200, 10), certIS = pattern(2400, 11);
        byte[] plain = PakeEmvProtocol.paddedCertificates(certC, certIS);
        check(plain.length == 8192);
        emit("padded_sha256", MessageDigest.getInstance("SHA-256").digest(plain));
        PakeEmvProtocol.Certificates certificates = PakeEmvProtocol.parseCertificates(plain);
        check(Arrays.equals(certC, certificates.certC));
        check(Arrays.equals(certIS, certificates.certIS));
        byte[] snapshot = plain.clone();
        plain[3604] = 0;
        rejects(() -> PakeEmvProtocol.parseCertificates(plain));
        System.arraycopy(snapshot, 0, plain, 0, plain.length);
        plain[8191] = 1;
        rejects(() -> PakeEmvProtocol.parseCertificates(plain));
        System.arraycopy(snapshot, 0, plain, 0, plain.length);
        plain[0] = (byte) 255; plain[1] = (byte) 255;
        rejects(() -> PakeEmvProtocol.parseCertificates(plain));
        System.arraycopy(snapshot, 0, plain, 0, plain.length);
        plain[0] = 0; plain[1] = 0;
        rejects(() -> PakeEmvProtocol.parseCertificates(plain));
        System.arraycopy(snapshot, 0, plain, 0, plain.length);
        plain[2] = 0; plain[3] = 0;
        rejects(() -> PakeEmvProtocol.parseCertificates(plain));
        rejects(() -> PakeEmvProtocol.parseCertificates(Arrays.copyOf(snapshot, 8191)));
        rejects(() -> PakeEmvProtocol.parseCertificates(Arrays.copyOf(snapshot, 8193)));
        byte[] maximum = PakeEmvProtocol.paddedCertificates(pattern(4096, 12), pattern(4091, 13));
        check(maximum[8191] == (byte) 128);
        certificates = PakeEmvProtocol.parseCertificates(maximum);
        check(certificates.certC.length == 4096 && certificates.certIS.length == 4091);
        rejects(() -> PakeEmvProtocol.paddedCertificates(new byte[4096], new byte[4092]));
        rejects(() -> PakeEmvProtocol.paddedCertificates(new byte[0], certIS));
        rejects(() -> PakeEmvProtocol.paddedCertificates(certC, new byte[0]));
        rejects(() -> PakeEmvProtocol.ctx1(new byte[831], x2));
        rejects(() -> PakeEmvProtocol.ctx1(x1, new byte[799]));
        rejects(() -> PakeEmvProtocol.kc1(new byte[31], ctx1, nu));
        rejects(() -> PakeEmvProtocol.kc1(tk, ctx1, new byte[31]));
        rejects(() -> PakeEmvProtocol.ctx2(new byte[63], ctx1));
        rejects(() -> PakeEmvProtocol.ctx3(new byte[8219], ctx2));
        rejects(() -> PakeEmvProtocol.ctx4(new byte[795], ctx3));
        rejects(() -> PakeEmvProtocol.pkh(new byte[799], pkIS));
        rejects(() -> PakeEmvProtocol.pkh(pkC, new byte[1311]));
        rejects(() -> PakeEmvProtocol.deriveKeys(tk, new byte[31], pkh, ctx4));
        rejects(() -> PakeEmvProtocol.ctx5(new byte[31], ctx4));
        System.err.println("PAKE-EMV Java: " + checks + " checks passed");
    }
}
